// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // Ensure the contract owner is not used as the caller to avoid onlyOwner restrictions
        vm.assume(caller != address(this));
        // Randomly set or unset the logger
        bool status = true;
        // Only the owner can call setApprovedLogger; we need to prank as owner
        // Since owner is private, we assume the deployer (this contract) is the owner
        vm.prank(address(this));
        c.setApprovedLogger(caller, status);
        // Now check the property: after setting to true, approvedToLog should return true
        bool result = c.approvedToLog(caller);
        assertTrue(result == status);
        // Flip status
        status = false;
        vm.prank(address(this));
        c.setApprovedLogger(caller, status);
        result = c.approvedToLog(caller);
        assertTrue(result == status);
    }
}

