import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        // Without prior setApprovedLogger call, the default is false.
        // We call approvedToLog directly using the caller's identity.
        // In the reference, an unapproved caller returns false.
        // In the mutant, it always returns false (so this also holds). 
        // But we need a rule that the mutant breaks.
        // The mutant returns false even for addresses that were approved.
        // So: if we first set a logger as approved, the reference returns true for that logger, the mutant returns false.
        // Let's test that scenario.
        c.setApprovedLogger(caller, true);
        bool result = c.approvedToLog(caller);
        assertTrue(result, "approvedToLog should return true for an approved logger");
    }
}

