pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _caller, address _keepAddress, address _requester, bytes32 _digest, uint256 _utxoSize, bytes memory _redeemerOutputScript, uint256 _requestedFee, bytes memory _outpoint, bytes32 _r, bytes32 _s, bytes32 _signingGroupPubkeyX, bytes32 _signingGroupPubkeyY, bytes32 _txid, bool _wasFraud) public {
        vm.assume(_caller != address(0));
        vm.assume(_utxoSize <= type(uint256).max / 2);
        vm.assume(_requestedFee <= type(uint256).max / 2);
        // Set up approved logger
        c.setApprovedLogger(_caller, true);
        // Test each log function
        vm.prank(_caller);
        bool createdResult = c.logCreated(_keepAddress);
        vm.prank(_caller);
        bool redemptionResult = c.logRedemptionRequested(_requester, _digest, _utxoSize, _redeemerOutputScript, _requestedFee, _outpoint);
        vm.prank(_caller);
        bool gotSigResult = c.logGotRedemptionSignature(_digest, _r, _s);
        vm.prank(_caller);
        bool pubkeyResult = c.logRegisteredPubkey(_signingGroupPubkeyX, _signingGroupPubkeyY);
        vm.prank(_caller);
        bool setupFailedResult = c.logSetupFailed();
        vm.prank(_caller);
        bool fraudResult = c.logFraudDuringSetup();
        vm.prank(_caller);
        bool fundedResult = c.logFunded();
        vm.prank(_caller);
        bool courtesyCalledResult = c.logCourtesyCalled();
        vm.prank(_caller);
        bool liquidationResult = c.logStartedLiquidation(_wasFraud);
        vm.prank(_caller);
        bool redeemedResult = c.logRedeemed(_txid);
        vm.prank(_caller);
        bool liquidatedResult = c.logLiquidated();
        vm.prank(_caller);
        bool exitedResult = c.logExitedCourtesyCall();
        // Assert that all return true for approved caller
        assertTrue(createdResult && redemptionResult && gotSigResult && pubkeyResult && setupFailedResult && fraudResult && fundedResult && courtesyCalledResult && liquidationResult && redeemedResult && liquidatedResult && exitedResult);
    }
}

