import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // Approve the caller if we want to test from an approved logger; not needed, any address works
        // The rule: c.logCourtesyCalled() returns true if and only if c.approvedToLog(caller) is false
        bool loggerApproved = c.approvedToLog(caller);
        bool returned;
        vm.prank(caller);
        returned = c.logCourtesyCalled();
        assertTrue(returned == !loggerApproved);
    }
}

