pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bool _wasFraud) public {
        // Set a random caller
        address caller = address(uint160(uint256(keccak256(abi.encode(_wasFraud, block.timestamp))) % 10000));
        vm.assume(caller != address(0));

        // Authorize the caller via the owner
        vm.prank(address(c)); // owner is deployer, which is this test contract
        c.setApprovedLogger(caller, true);

        // Call from the approved logger
        vm.prank(caller);
        bool returned = c.logStartedLiquidation(_wasFraud);

        // General rule: the return value should equal approvedToLog(caller) which is true
        assertTrue(c.approvedToLog(caller) == returned);
    }
}

