pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bool _approved) public {
        // We need to grant the test contract owner role to call setApprovedLogger
        // But the test contract is not the owner; we need to use vm.prank with the owner address
        // However, owner is private; we can't read it. But we can work around by setting the owner via the constructor?
        // Actually we can deploy C then call setApprovedLogger from the owner who created it.
        // The deployer of C is the owner. The test contract deploys C, so the test contract is the owner.
        // We need to set approvedLoggers[address(this)] = true before calling logStartedLiquidation
        c.setApprovedLogger(address(this), _approved);
        // Now call logStartedLiquidation
        bool ret = c.logStartedLiquidation(true);
        // The rule: if caller is approved, the return value should be true
        // Condition: we use vm.assume to restrict? Actually we want a general rule that holds on reference.
        // For reference: returns true when approved, false otherwise.
        // So the rule: ret == c.approvedToLog(address(this))
        assertTrue(ret == c.approvedToLog(address(this)));
    }
}

