pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, bool wasFraud) public {
        // The reference C: logStartedLiquidation returns true for approved callers, false otherwise.
        // For any caller, if logStartedLiquidation returns false, then approvedToLog(caller) must be false.
        // In the buggy version, logStartedLiquidation always returns false, so approvedToLog(caller) would be false even for approved callers.
        // We prank the caller to simulate the call.
        vm.prank(caller);
        bool result = c.logStartedLiquidation(wasFraud);
        if (!result) {
            assertTrue(!c.approvedToLog(caller), "If logStartedLiquidation returns false, caller must not be approved");
        }
    }
}

