pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bool isApproved, address caller) public {
        // Arrange: set the approved status for the caller
        address owner = address(this);
        vm.startPrank(owner);
        c.setApprovedLogger(caller, isApproved);
        vm.stopPrank();

        // Act: call logStartedLiquidation as the caller
        vm.prank(caller);
        bool returnValue = c.logStartedLiquidation(false);

        // Assert: the return value should equal the caller's approval status
        assertTrue(returnValue == isApproved);
    }
}

