pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, bool isApproved) public {
        // Assume caller is not the owner to avoid onlyOwner modifier issues
        vm.assume(caller != address(this)); 

        // Set approval status for the caller
        vm.prank(address(this)); // Owner sets the approval
        c.setApprovedLogger(caller, isApproved);

        // Call logLiquidated from the caller
        vm.prank(caller);
        bool result = c.logLiquidated();

        // General rule: logLiquidated returns true if and only if the caller is NOT an approved logger
        assertTrue(result == !isApproved);
    }
}
